//
// xsd:date against xsd:dateTime stays comparable. That is a deliberate extension
// — the specification's operator table lists xsd:dateTime alone — and a date is
// midnight on that day, which is a real instant.
func temporalDatatypesComparable(left, right string) bool {
	if !isTemporalDatatypeIRI(left) || !isTemporalDatatypeIRI(right) {
		return false
